args.sparql:
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT DISTINCT ?s WHERE {
  ?s rdfs:label ?label .
  FILTER (STR(?label) = "I Can't See Myself Leaving You"@en)
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX foaf: <http://xmlns.com/foaf/0.1/>

SELECT DISTINCT ?artist ?artistLabel ?deathPlace WHERE {
  ?song rdfs:label ?label .
  FILTER (STR(?label) = "I Can't See Myself Leaving You"@en)
  {
    ?song dbo:artist ?artist .
  } UNION {
    ?song dbp:artist ?artist .
  } UNION {
    ?song foaf:maker ?artist .
  }
  ?artist dbo:deathPlace ?deathPlace .
  OPTIONAL { ?artist rdfs:label ?artistLabel . FILTER (langMatches(lang(?artistLabel), "EN")) }
}

